"""Load SwiftCode's canonical runner for the bundled module entry point.

Both bridge/main.py and `python -m google.antigravity` must execute the same
provider/auth logic. This file is SwiftCode integration code, not upstream SDK
code. Fail explicitly if the app's bridge resource is missing.
"""
from importlib.util import module_from_spec, spec_from_file_location
from pathlib import Path
import sys

_runner_path = Path(__file__).resolve().parents[7] / "bridge" / "agent_runner.py"
_spec = spec_from_file_location("_swiftcode_agent_runner", _runner_path)
if _spec is None or _spec.loader is None:
    raise ImportError(f"SwiftCode bridge runner is missing at {_runner_path}")
_module = module_from_spec(_spec)
sys.modules[_spec.name] = _module
_spec.loader.exec_module(_module)
AgentRunner = _module.AgentRunner
